<?php

/*
 * Nagad specifics. The shared behaviour (verification, races, retries, sync)
 * is covered by ConformanceTest via tests/Conformance/NagadScenario.php.
 * All keys are throwaway pairs generated by the scenario.
 */

use ByteMinus\BdPayGate\Contracts\SupportsRefunds;
use ByteMinus\BdPayGate\Drivers\Nagad\NagadCrypto;
use ByteMinus\BdPayGate\Drivers\NagadGateway;
use ByteMinus\BdPayGate\Enums\PaymentStatus;
use ByteMinus\BdPayGate\Exceptions\GatewayException;
use ByteMinus\BdPayGate\Exceptions\UnsupportedOperationException;
use ByteMinus\BdPayGate\Facades\BdPayGate;
use ByteMinus\BdPayGate\Models\Payment;
use ByteMinus\BdPayGate\Tests\Conformance\NagadScenario;
use Illuminate\Http\Client\Request;
use Illuminate\Support\Facades\Http;

/**
 * Boot the simulated Nagad. Overrides take precedence over the default stubs
 * (Http::fake uses the first matching stub, so they cannot be added later).
 *
 * @param  array<string, mixed>|Closure(NagadScenario): array<string, mixed>  $overrides
 */
function nagadScenario(array $config = [], array|Closure $overrides = []): NagadScenario
{
    $s = new NagadScenario;
    config()->set('bdpaygate.gateways.nagad', array_merge($s->config(), $config));
    Http::fake(($overrides instanceof Closure ? $overrides($s) : $overrides) + $s->stubs());

    return $s;
}

function nagadPayment(): Payment
{
    return Payment::query()->where('gateway', 'nagad')->latest('id')->firstOrFail();
}

function nagadBareKey(string $pem): string
{
    return (string) preg_replace('/-----[A-Z ]+-----|\s+/', '', $pem);
}

it('initializes with an encrypted, signed payload and the KM headers, then completes', function () {
    $s = nagadScenario(['ip' => '203.0.113.10']);
    $this->travelTo(now('UTC')->setDate(2026, 10, 15)->setTime(0, 30, 0));

    $payment = BdPayGate::driver('nagad')->charge(150, 'ORD-1', customer(), 'Order 1');

    expect($payment->gateway_payment_id)->toBe('MDREF'.$payment->gateway_reference)
        ->and($payment->checkout_url)->toStartWith('https://sandbox-ssl.mynagad.com:10061/check-out/');

    Http::assertSent(function (Request $r) use ($s, $payment) {
        if (! str_contains($r->url(), '/check-out/initialize/')) {
            return false;
        }

        $plain = $s->readSensitive($r);

        return $r->url() === 'https://'.NagadScenario::BASE.'/check-out/initialize/'.NagadScenario::MERCHANT_ID.'/'.$payment->gateway_reference.'?locale=EN'
            && $r->method() === 'POST'
            && $r->hasHeader('X-KM-Api-Version', 'v-0.2.0')
            && $r->hasHeader('X-KM-IP-V4', '203.0.113.10')
            && $r->hasHeader('X-KM-Client-Type', 'PC_WEB')
            && $r['dateTime'] === '20261015063000' // Asia/Dhaka, UTC+6
            && $plain['datetime'] === '20261015063000'
            && $plain['merchantId'] === NagadScenario::MERCHANT_ID
            && $plain['orderId'] === $payment->gateway_reference
            && preg_match('/^[0-9a-f]{40}$/', $plain['challenge']) === 1
            && ! isset($r['accountNumber']);
    });

    Http::assertSent(function (Request $r) use ($s, $payment) {
        if (! str_contains($r->url(), '/check-out/complete/')) {
            return false;
        }

        $plain = $s->readSensitive($r);

        return str_ends_with($r->url(), '/check-out/complete/MDREF'.$payment->gateway_reference)
            && $plain === [
                'merchantId' => NagadScenario::MERCHANT_ID,
                'orderId' => $payment->gateway_reference,
                'amount' => '150.00',
                'currencyCode' => '050',
                'challenge' => $plain['challenge'],
            ]
            && str_ends_with($r['merchantCallbackURL'], '/bdpaygate/nagad/callback')
            && $r['additionalMerchantInfo'] === ['reference' => 'ORD-1']
            && $r->hasHeader('X-KM-Api-Version', 'v-0.2.0');
    });
});

it('echoes the challenge nagad returned when completing', function () {
    $challenges = [];
    nagadScenario([], function (NagadScenario $s) use (&$challenges) {
        return [
            NagadScenario::BASE.'/check-out/initialize/*' => function (Request $r) use ($s) {
                $plain = $s->readSensitive($r);

                return Http::response(NagadScenario::seal(['paymentReferenceId' => 'MDREF1', 'challenge' => 'NAGADCHALLENGE', 'acceptDateTime' => $plain['datetime']]));
            },
            NagadScenario::BASE.'/check-out/complete/*' => function (Request $r) use ($s, &$challenges) {
                $challenges[] = $s->readSensitive($r)['challenge'];

                return Http::response(['callBackUrl' => 'https://x', 'status' => 'Success']);
            },
        ];
    });

    BdPayGate::driver('nagad')->charge(10, 'ORD-C', customer());

    expect($challenges)->toBe(['NAGADCHALLENGE']);
});

it('sends a fresh 20 character alphanumeric order id per attempt', function () {
    nagadScenario();

    $first = BdPayGate::driver('nagad')->charge(100, 'ORD-SAME', customer());
    $second = BdPayGate::driver('nagad')->charge(100, 'ORD-SAME', customer());

    expect($first->gateway_reference)->toMatch('/^[A-Z0-9]{20}$/')
        ->and($second->gateway_reference)->toMatch('/^[A-Z0-9]{20}$/')
        ->and($second->gateway_reference)->not->toBe($first->gateway_reference);
});

it('refuses an order id nagad would reject', function () {
    nagadScenario();
    config()->set('bdpaygate.gateways.nagadbad', (new NagadScenario)->config() + ['driver' => 'nagad-bad']);
    config()->set('bdpaygate.gateways.nagadbad.driver', 'nagad-bad');
    BdPayGate::extend('nagad-bad', fn ($app, array $config, string $name) => new class($config, $name) extends NagadGateway
    {
        protected function newGatewayReference(): string
        {
            return 'BAD_ORDER_ID';
        }
    });

    expect(fn () => BdPayGate::driver('nagadbad')->charge(100, 'ORD-BAD', customer()))
        ->toThrow(GatewayException::class, 'must be 5 to 20 letters or digits');
    Http::assertNothingSent();
});

it('signs with sha1 when configured', function () {
    $s = nagadScenario(['signature_algorithm' => 'sha1']);
    $s->algorithm = OPENSSL_ALGO_SHA1;

    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-SHA1', customer());

    expect($payment->checkout_url)->not->toBeEmpty();
});

it('signs with sha256 by default, which a sha1 verifier rejects', function () {
    $s = nagadScenario();
    $s->algorithm = OPENSSL_ALGO_SHA1;

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-SHA', customer()))
        ->toThrow(RuntimeException::class, 'signature does not verify');
});

it('rejects an unknown signature algorithm', function () {
    nagadScenario(['signature_algorithm' => 'md5']);

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-MD5', customer()))
        ->toThrow(GatewayException::class, 'Unsupported Nagad signature algorithm');
});

it('round-trips the RSA envelope with PEM, bare base64, escaped and file keys', function () {
    $keys = NagadScenario::keys();
    $file = tempnam(sys_get_temp_dir(), 'nagad');
    file_put_contents($file, $keys['merchant_private']);

    $variants = [
        new NagadCrypto($keys['nagad_public'], $keys['merchant_private']),
        new NagadCrypto(nagadBareKey($keys['nagad_public']), nagadBareKey($keys['merchant_private'])),
        new NagadCrypto(str_replace("\n", '\n', $keys['nagad_public']), str_replace("\n", '\n', $keys['merchant_private'])),
        new NagadCrypto($keys['nagad_public'], $file, 'SHA256withRSA'),
    ];

    foreach ($variants as $crypto) {
        $plain = '{"merchantId":"683002007104225","orderId":"BP123"}';

        openssl_private_decrypt(base64_decode($crypto->encrypt($plain)), $decrypted, $keys['nagad_private'], OPENSSL_PKCS1_PADDING);
        expect($decrypted)->toBe($plain)
            ->and(openssl_verify($plain, base64_decode($crypto->sign($plain)), $keys['merchant_public'], OPENSSL_ALGO_SHA256))->toBe(1);

        $sealed = NagadScenario::seal(['paymentReferenceId' => 'MDREF1']);
        $opened = $crypto->decrypt($sealed['sensitiveData']);
        expect(json_decode($opened, true))->toBe(['paymentReferenceId' => 'MDREF1'])
            ->and($crypto->verify($opened, $sealed['signature']))->toBeTrue()
            ->and($crypto->verify($opened.'x', $sealed['signature']))->toBeFalse();
    }

    @unlink($file);
});

it('fails clearly on an unreadable key', function () {
    $crypto = new NagadCrypto('not-a-key', NagadScenario::keys()['merchant_private']);

    expect(fn () => $crypto->encrypt('x'))->toThrow(GatewayException::class, 'Could not read the Nagad public key');
});

it('rejects an initialize response whose signature does not verify', function () {
    nagadScenario([], [NagadScenario::BASE.'/check-out/initialize/*' => fn () => Http::response(
        ['signature' => base64_encode('forged')] + NagadScenario::seal(['paymentReferenceId' => 'MDREF1', 'challenge' => 'c']),
    )]);

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-SIG', customer()))
        ->toThrow(GatewayException::class, 'signature does not verify');
    Http::assertNotSent(fn (Request $r) => str_contains($r->url(), '/check-out/complete/'));
});

it('accepts an unverified response signature when verification is off', function () {
    nagadScenario(['verify_response_signature' => false], [
        NagadScenario::BASE.'/check-out/initialize/*' => fn () => Http::response(
            ['signature' => 'garbage'] + NagadScenario::seal(['paymentReferenceId' => 'MDREF1', 'challenge' => 'c']),
        ),
        NagadScenario::BASE.'/check-out/complete/*' => Http::response(['callBackUrl' => 'https://x', 'status' => 'Success']),
    ]);

    expect(BdPayGate::driver('nagad')->charge(100, 'ORD-NOSIG', customer())->checkout_url)->toBe('https://x');
});

it('surfaces nagad error envelopes', function () {
    nagadScenario([], [NagadScenario::BASE.'/check-out/initialize/*' => Http::response(['reason' => '16_0006_076', 'message' => 'Transaction Date Time Not in allowed window'], 400)]);

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-ERR', customer()))
        ->toThrow(GatewayException::class, 'Transaction Date Time Not in allowed window [16_0006_076]');

    expect(Payment::query()->firstOrFail()->gatewayResponse('initialize'))->toMatchArray(['reason' => '16_0006_076']);
});

it('keeps the paymentRefId when the complete call fails, so sync can settle it', function () {
    nagadScenario([], [
        NagadScenario::BASE.'/check-out/complete/*' => Http::response(['reason' => '16_0006_059', 'message' => 'Invalid Sensitive Data'], 400),
    ]);

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-LOST', customer()))->toThrow(GatewayException::class);

    $payment = Payment::query()->firstOrFail();
    expect($payment->gateway_payment_id)->toBe('MDREF'.$payment->gateway_reference)
        ->and(BdPayGate::sync($payment)->status)->toBe(PaymentStatus::Completed);
});

it('verifies with the stored paymentRefId, not the one in the callback', function () {
    $s = nagadScenario();
    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-REF', customer());

    $this->get('/bdpaygate/nagad/callback?'.http_build_query([
        'order_id' => $payment->gateway_reference,
        'payment_ref_id' => 'SOMEONE-ELSES-PAID-REF',
        'status' => 'Success',
    ]))->assertRedirect('/thanks?payment='.$payment->id);

    Http::assertSent(fn (Request $r) => str_ends_with($r->url(), '/verify/payment/'.$payment->gateway_payment_id) && $r->method() === 'GET');
    Http::assertNotSent(fn (Request $r) => str_contains($r->url(), 'SOMEONE-ELSES'));

    expect($payment->refresh()->status)->toBe(PaymentStatus::Completed)
        ->and($payment->gateway_transaction_id)->toBe('ISS'.substr($payment->gateway_reference, 2, 8));
});

it('does not complete when verify returns another order', function () {
    nagadScenario([], fn (NagadScenario $s) => [
        NagadScenario::BASE.'/verify/payment/*' => fn () => Http::response(['orderId' => 'BPOTHERORDER00000000'] + $s->verifyBody(nagadPayment(), 'Success')),
    ]);
    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-OTHER', customer());

    $this->get('/bdpaygate/nagad/callback?order_id='.$payment->gateway_reference)->assertRedirect('/failed');

    expect($payment->refresh()->status)->toBe(PaymentStatus::Pending);
});

it('compares amounts numerically, whatever decimals nagad sends', function (string $reported) {
    nagadScenario([], fn (NagadScenario $s) => [
        NagadScenario::BASE.'/verify/payment/*' => fn () => Http::response(['amount' => $reported] + $s->verifyBody(nagadPayment(), 'Success')),
    ]);
    $payment = BdPayGate::driver('nagad')->charge(130, 'ORD-AMT', customer());

    $this->get('/bdpaygate/nagad/callback?order_id='.$payment->gateway_reference);

    expect($payment->refresh()->status)->toBe(PaymentStatus::Completed);
})->with(['130', '130.0', '130.00']);

it('stays pending when verify does not know the payment yet', function () {
    nagadScenario([], [NagadScenario::BASE.'/verify/payment/*' => Http::response(['reason' => '16_0004_999', 'message' => 'Please verify provided data and try again'], 404)]);
    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-404', customer());

    expect(BdPayGate::sync($payment)->status)->toBe(PaymentStatus::Pending)
        ->and($payment->refresh()->gatewayResponse('sync'))->toMatchArray(['reason' => '16_0004_999', 'http_status' => 404]);
});

it('maps verified statuses', function (string $status, PaymentStatus $expected) {
    nagadScenario([], fn (NagadScenario $s) => [
        NagadScenario::BASE.'/verify/payment/*' => fn () => Http::response($s->verifyBody(nagadPayment(), $status)),
    ]);
    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-MAP', customer());

    expect(BdPayGate::sync($payment)->status)->toBe($expected);
})->with([
    ['Cancelled', PaymentStatus::Cancelled],
    ['Aborted', PaymentStatus::Cancelled],
    ['Failed', PaymentStatus::Failed],
    ['Fraud', PaymentStatus::Failed],
    ['UnKnownFailed', PaymentStatus::Failed],
    ['InProgress', PaymentStatus::Pending],
    ['PinGiven', PaymentStatus::Pending],
    ['SomethingNew', PaymentStatus::Pending],
]);

it('uses a public customer ip, and the configured ip otherwise', function () {
    nagadScenario(['ip' => '203.0.113.10']);

    BdPayGate::driver('nagad')->charge(100, 'ORD-IP1', customer(), null, ['customer_ip' => '198.51.100.7']);
    BdPayGate::driver('nagad')->charge(100, 'ORD-IP2', customer(), null, ['customer_ip' => '192.168.1.5']);

    Http::assertSent(fn (Request $r) => str_contains($r->url(), 'initialize') && $r->hasHeader('X-KM-IP-V4', '198.51.100.7'));
    Http::assertSent(fn (Request $r) => str_contains($r->url(), 'initialize') && $r->hasHeader('X-KM-IP-V4', '203.0.113.10'));
});

it('honours base_url, merchant_number, locale and client type', function () {
    nagadScenario([
        'base_url' => 'http://sandbox.mynagad.com:30001/api/dfs/',
        'merchant_number' => '01700000000',
        'locale' => 'bn',
        'client_type' => 'MOBILE_WEB',
    ], [
        'sandbox.mynagad.com:30001/api/dfs/check-out/initialize/*' => fn () => Http::response(NagadScenario::seal(['paymentReferenceId' => 'MDREF9', 'challenge' => 'c'])),
        'sandbox.mynagad.com:30001/api/dfs/check-out/complete/*' => Http::response(['callBackUrl' => 'https://x', 'status' => 'Success']),
    ]);

    BdPayGate::driver('nagad')->charge(100, 'ORD-BASE', customer());

    Http::assertSent(fn (Request $r) => str_starts_with($r->url(), 'http://sandbox.mynagad.com:30001/api/dfs/check-out/initialize/')
        && str_ends_with($r->url(), '?locale=BN')
        && $r['accountNumber'] === '01700000000'
        && $r->hasHeader('X-KM-Client-Type', 'MOBILE_WEB'));
});

it('has no refund API', function () {
    nagadScenario();
    $payment = BdPayGate::driver('nagad')->charge(100, 'ORD-RF', customer());

    expect(BdPayGate::driver('nagad'))->not->toBeInstanceOf(SupportsRefunds::class)
        ->and(fn () => BdPayGate::refund($payment))->toThrow(UnsupportedOperationException::class);
});

it('refuses non-BDT charges', function () {
    nagadScenario();
    config()->set('bdpaygate.currency', 'USD');

    expect(fn () => BdPayGate::driver('nagad')->charge(100, 'ORD-USD', customer()))->toThrow(GatewayException::class, 'only accepts BDT');
});
